<script setup lang="ts">
import { computed } from 'vue';
const props=defineProps<{workDays:number;workingDays:number;canLeave:boolean;canHistory:boolean;canPayroll:boolean;recentLeaves:Array<{id:string;title:string;date:string;status:string;statusLabel:string}>;loading?:boolean}>();
