const percent=computed(()=>Math.min(100,Math.round((props.workDays/Math.max(1,props.workingDays))*100)));
</script>
<template>
  <div class="side-stack">
    <section class="dashboard-card summary-card">
      <div class="card-heading"><div><h3>Ca làm việc &amp; Thống kê</h3><p>Tiến độ tháng đang chọn</p></div></div>
      <div class="progress-wrap">
        <div class="progress-ring" :style="{'--progress':`${percent*3.6}deg`}"><div><strong>{{ percent }}%</strong><span>Hoàn thành</span></div></div>
        <div class="progress-copy"><span>Mục tiêu tháng</span><strong>{{ workingDays }} ngày công</strong><span>Đã hoàn thành</span><b>{{ workDays }} ngày công</b></div>
      </div>
      <nav class="quick-actions" aria-label="Truy cập nhanh">
        <button v-if="canLeave" class="quick-action-leave" @click="emit('navigate','leave')"><span class="action-icon leave"><v-icon icon="mdi-calendar-minus-outline" size="18"/></span><span>Xin nghỉ phép</span><v-icon icon="mdi-chevron-right" size="18"/></button>
        <button v-if="canHistory" @click="emit('navigate','history')"><span class="action-icon history"><v-icon icon="mdi-history" size="18"/></span><span>Lịch sử chấm công</span><v-icon icon="mdi-chevron-right" size="18"/></button>
        <button v-if="canPayroll" class="quick-action-payroll" @click="emit('navigate','payroll')"><span class="action-icon payroll"><v-icon icon="mdi-cash-multiple" size="18"/></span><span>Xem thu nhập</span><v-icon icon="mdi-chevron-right" size="18"/></button>
      </nav>
    </section>
    <section class="dashboard-card notices-card">
      <div class="card-heading"><div><h3>Đơn nghỉ gần đây</h3><p>Trạng thái yêu cầu của bạn</p></div><button v-if="canLeave" class="text-action" @click="emit('navigate','leave')">Xem tất cả</button></div>
      <div v-if="loading" class="notice-loading"/>
      <div v-else-if="recentLeaves.length" class="notice-list"><article v-for="leave in recentLeaves" :key="leave.id"><span class="notice-icon"><v-icon icon="mdi-calendar-minus-outline" size="18"/></span><div><strong>{{ leave.title }}</strong><small>{{ leave.date }}</small></div><span class="leave-status" :class="`status-${leave.status}`">{{ leave.statusLabel }}</span></article></div>
      <div v-else class="empty-notice"><v-icon icon="mdi-bell-sleep-outline" size="25"/><strong>Không có cập nhật mới</strong><span>Đơn nghỉ gần nhất sẽ xuất hiện tại đây.</span></div>
    </section>
  </div>
</template>
